// n8n node "Pick pictures" (W8). Your own list of public https links, each with an optional label you expect.
// Edit the list below. Links to private networks, other protocols and non-picture files are refused.
const SCENES = ['own_wallbox', 'shared_garage', 'street_parking', 'public_charger', 'no_charging_visible', 'not_a_parking_scene'];
const LIST = [
  // { url: 'https://example.org/my-test-picture.jpg', expect: 'shared_garage' },
];
const PRIVATE = /^(localhost|127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.|\[?::1\]?$|0\.0\.0\.0)/i;
const out = [];
const refused = [];
for (const item of LIST.slice(0, 10)) {
  let ok = false;
  try {
    const u = new URL(String(item.url));
    ok = u.protocol === 'https:' && !PRIVATE.test(u.hostname) && /\.(jpe?g|png|webp)$/i.test(u.pathname) && !u.username && !u.password;
  } catch (e) { ok = false; }
  if (!ok) { refused.push(String(item.url).slice(0, 60)); continue; }
  out.push({ json: { url: item.url, expect: SCENES.includes(item.expect) ? item.expect : null } });
}
if (out.length === 0) throw new Error('Add at least one public https picture link (.jpg, .png or .webp) in the node "Pick pictures". Refused: ' + refused.length);
return out;

// n8n node "Build request" (W8). The vision step's description is the only input to Jev: one closed question, one "none" option.
const SCENES = ['own_wallbox', 'shared_garage', 'street_parking', 'public_charger', 'no_charging_visible', 'not_a_parking_scene'];
// One output per picture, paired with "Pick pictures" by position.
const picked = $('Pick pictures').all().map((i) => i.json);
return $input.all().map((it, n) => {
const first = it.json;
const raw = first.content && first.content[0] && typeof first.content[0].text === 'string' ? first.content[0].text : String(first.description ?? '');
const description = raw.replace(/\s+/g, ' ').replace(/https?:\/\/\S+/gi, '').slice(0, 600).trim();
const url = picked[n] ? picked[n].url : null;
const expect = picked[n] ? picked[n].expect : null;
return { json: {
  url, expect, described: description.length > 0,
  request: {
    state: description,
    model: 'jev-latest',
    questions: {
      scene: {
        type: 'choice',
        instructions: 'The text describes a photo. Say which parking or charging situation it shows. Choose only from what the text says. If the text does not say, choose not_a_parking_scene or no_charging_visible.',
        criteria: {
          own_wallbox: 'a charging box or socket on a private house or a car park bay the person owns',
          shared_garage: 'a shared or underground garage with several bays and no visible charging point',
          street_parking: 'cars parked along a street, no charging point',
          public_charger: 'a public charging station or charging post in a public place',
          no_charging_visible: 'a parking place where no charging point is mentioned',
          not_a_parking_scene: 'the text is not about parking or charging',
        },
      },
    },
  },
} };
});

// n8n node "Tally" (W8). Closed names and counts only. A picture link is kept out of the result.
const SCENES = ['own_wallbox', 'shared_garage', 'street_parking', 'public_charger', 'no_charging_visible', 'not_a_parking_scene'];
const items = $input.all().map((i) => i.json);
// Jev's reply replaces the item, so the label you expected is read back from "Build request" by position.
const built = $('Build request').all().map((i) => i.json);
const rows = items.map((j, n) => {
  const a = j.answers && j.answers.scene ? j.answers.scene : {};
  const choice = SCENES.includes(a.choice) ? a.choice : 'none';
  const confidence = typeof a.confidence === 'number' ? Math.max(0, Math.min(1, a.confidence)) : 0;
  return { choice, confidence, expect: j.expect ?? (built[n] && built[n].expect) ?? null };
});
const labelled = rows.filter((r) => r.expect);
return [{ json: {
  pictures: rows.length,
  answered: rows.filter((r) => r.choice !== 'none').length,
  labelled: labelled.length,
  agreeWithYourLabel: labelled.filter((r) => r.choice === r.expect).length,
  lowConfidence: rows.filter((r) => r.confidence < 0.5).length,
  note: 'A handful of pictures proves nothing about accuracy in the wild. Nothing here goes into the app without Martin\'s decision.',
} }];
